WITH RECURSIVE des(c) AS (SELECT point_code FROM kg_edge WHERE pre_code = :code AND subject_id = CAST(:subject_id AS INTEGER) UNION SELECT e.point_code FROM kg_edge e JOIN des ON e.pre_code = des.c WHERE e.subject_id = CAST(:subject_id AS INTEGER)) SELECT p.code AS code, p.title AS title FROM kg_point p WHERE p.code IN (SELECT c FROM des) AND p.code <> :code AND p.subject_id = CAST(:subject_id AS INTEGER) ORDER BY p.id
